<?php
function throttle(string $action,string $who,int $max=6,int $window=900): void {
 $key=hash('sha256',$action.'|'.$who); transaction(function()use($key,$max,$window){
  execute('INSERT IGNORE INTO gioi_han_xac_thuc(khoa,so_lan,bat_dau) VALUES (?,0,NOW())',[$key]);
  $r=db_one('SELECT * FROM gioi_han_xac_thuc WHERE khoa=? FOR UPDATE',[$key]);
  if(strtotime($r['bat_dau'])<time()-$window){execute('UPDATE gioi_han_xac_thuc SET so_lan=1,bat_dau=NOW() WHERE khoa=?',[$key]);return;}
  must((int)$r['so_lan']<$max,'Bạn đã thử quá nhiều lần. Vui lòng chờ rồi thử lại.',429);
  execute('UPDATE gioi_han_xac_thuc SET so_lan=so_lan+1 WHERE khoa=?',[$key]);
 });
}
function master_key(): string { $c=private_config('app_key'); if(empty($c['key'])){ $c=['key'=>base64_encode(random_bytes(32))];private_save('app_key',$c); }$k=base64_decode($c['key'],true);must(is_string($k)&&strlen($k)===32,'Khóa ứng dụng không hợp lệ.',500);return $k; }
function encrypt_secret(string $text): string { $iv=random_bytes(12);$tag='';$c=openssl_encrypt($text,'aes-256-gcm',master_key(),OPENSSL_RAW_DATA,$iv,$tag);return base64_encode($iv.$tag.$c); }
function decrypt_secret(string $text): string { $b=base64_decode($text,true);must(is_string($b)&&strlen($b)>28,'Không đọc được cấu hình xác thực.',500);$r=openssl_decrypt(substr($b,28),'aes-256-gcm',master_key(),OPENSSL_RAW_DATA,substr($b,0,12),substr($b,12,16));must($r!==false,'Không giải mã được cấu hình xác thực.',500);return $r; }
function base32_secret(): string { $s='';$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';for($i=0;$i<32;$i++)$s.=$a[random_int(0,31)];return $s; }
function totp(string $secret,int $counter): string { $bits='';$abc='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';foreach(str_split($secret)as$c)$bits.=str_pad(decbin(strpos($abc,$c)),5,'0',STR_PAD_LEFT);$key='';foreach(str_split($bits,8)as$b)if(strlen($b)===8)$key.=chr(bindec($b));$h=hash_hmac('sha1',pack('N2',0,$counter),$key,true);$o=ord($h[19])&15;$n=unpack('N',substr($h,$o,4))[1]&0x7fffffff;return str_pad((string)($n%1000000),6,'0',STR_PAD_LEFT); }
function totp_counter(string $secret,string $code,int $last=0): ?int { if(!preg_match('/^[0-9]{6}$/D',$code))return null;$now=intdiv(time(),30);foreach([$now,$now-1,$now+1]as$c)if($c>$last&&hash_equals(totp($secret,$c),$code))return $c;return null; }
function auth_complete(array $u): never { if($u['quyen']==='ADMIN'&&setting('admin_2fa')){session_regenerate_id(true);$_SESSION=['pending_admin_id'=>(int)$u['id'],'pending_at'=>time(),'csrf'=>bin2hex(random_bytes(32))];redirect('admin/xac_minh_otp.php');}$appointment=$_SESSION['appointment_after_login']??'';login_user($u);if($u['quyen']==='KHACH_HANG'&&is_string($appointment)&&preg_match('~^khach_hang/lich_hen\.php\?(?:vin=[A-Za-z0-9]{17}|dat_lich=1)$~D',$appointment))redirect($appointment);redirect(login_destination($u['quyen'])); }
function smtp_send(string $to,string $subject,string $body): void { $c=private_config('integrations')['smtp']??[];must(!empty($c['host'])&&!empty($c['from']),'Chức năng email chưa được quản trị cấu hình.');$m=new PHPMailer\PHPMailer\PHPMailer(true);$m->isSMTP();$m->Host=$c['host'];$m->Port=(int)($c['port']??587);$m->SMTPAuth=!empty($c['username']);$m->Username=$c['username']??'';$m->Password=$c['password']??'';$m->SMTPSecure=$c['secure']??'tls';$m->CharSet='UTF-8';$m->setFrom($c['from'],'Showroom Auto');$m->addAddress($to);$m->Subject=$subject;$m->Body=$body;$m->Timeout=15;$m->send(); }
function http_json(string $url,?array $body=null,array $headers=[]): array { must(str_starts_with($url,'https://'),'Dịch vụ phải sử dụng HTTPS.');$ch=curl_init($url);$opts=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_HTTPHEADER=>$headers];if($body!==null){$opts[CURLOPT_POST]=true;$opts[CURLOPT_POSTFIELDS]=http_build_query($body);}curl_setopt_array($ch,$opts);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);must($raw!==false&&$code>=200&&$code<300,'Dịch vụ bên ngoài chưa phản hồi thành công.');$data=json_decode($raw,true);must(is_array($data),'Phản hồi dịch vụ không hợp lệ.');return $data; }
function sms_send(string $phone,string $code): void { $c=private_config('integrations')['twilio']??[];must(!empty($c['sid'])&&!empty($c['token'])&&!empty($c['from']),'Chức năng SMS chưa được quản trị cấu hình.');must((bool)preg_match('/^AC[a-fA-F0-9]{32}$/D',$c['sid']),'Cấu hình SMS chưa hợp lệ.');$ch=curl_init('https://api.twilio.com/2010-04-01/Accounts/'.$c['sid'].'/Messages.json');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_USERPWD=>$c['sid'].':'.$c['token'],CURLOPT_POSTFIELDS=>http_build_query(['To'=>$phone,'From'=>$c['from'],'Body'=>'Ma xac thuc Showroom Auto: '.$code.'. Hieu luc 5 phut.']),CURLOPT_TIMEOUT=>20]);$r=curl_exec($ch);$s=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);must($r!==false&&$s>=200&&$s<300,'Chưa gửi được SMS.'); }
function send_otp(array $u,string $purpose,string $channel): string { throttle('otp-user',(string)$u['id'],3,300);$id=uid('OTP');$code=(string)random_int(100000,999999);$hash=password_hash($code,PASSWORD_DEFAULT);$expires=date('Y-m-d H:i:s',time()+300);if($channel==='sms')sms_send($u['sdt_dang_nhap']?:$u['so_dien_thoai'],$code);else smtp_send($u['email'],'Mã xác thực Showroom Auto','Mã xác thực của bạn: '.$code.'. Mã có hiệu lực 5 phút.');transaction(function()use($u,$purpose,$id,$hash,$expires){execute('UPDATE otp_thu_thach SET da_dung_luc=NOW() WHERE tai_khoan_id=? AND muc_dich=? AND da_dung_luc IS NULL',[$u['id'],$purpose]);execute('INSERT INTO otp_thu_thach(id,tai_khoan_id,muc_dich,otp_hash,het_han) VALUES (?,?,?,?,?)',[$id,$u['id'],$purpose,$hash,$expires]);});return $id; }
function check_otp(string $id,string $code): array { $r=transaction(function()use($id,$code){$r=db_one('SELECT * FROM otp_thu_thach WHERE id=? FOR UPDATE',[$id]);must($r&&$r['da_dung_luc']===null&&strtotime($r['het_han'])>time()&&(int)$r['so_lan_sai']<5,'Mã không còn hiệu lực.');if(!password_verify($code,$r['otp_hash'])){execute('UPDATE otp_thu_thach SET so_lan_sai=so_lan_sai+1 WHERE id=?',[$id]);return null;}execute('UPDATE otp_thu_thach SET da_dung_luc=NOW() WHERE id=?',[$id]);return $r;});must($r!==null,'Mã xác thực không đúng.');return $r; }
